public class Blog {
    public int Id { get; set; }
    public string Url { get; set; }
    public virtual List<Post> Posts { get; set; } // virtual for lazy loading
}

// Eager Loading
var blog = await context.Blogs
    .Include(b => b.Posts)
    .FirstOrDefaultAsync(b => b.Id == 1);

// Explicit Loading
var blog = await context.Blogs.FirstAsync(b => b.Id == 1);
await context.Entry(blog)
    .Collection(b => b.Posts)
    .LoadAsync();

// Lazy Loading (requires Microsoft.EntityFrameworkCore.Proxies)
var blog = await context.Blogs.FirstAsync(b => b.Id == 1);
var posts = blog.Posts; // Triggers query
